<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/config/config.php';require APP_ROOT.'/app/core/database.php';require APP_ROOT.'/app/modules/profile/profile.php';require APP_ROOT.'/app/modules/searches/searches.php';
try{$uid=local_user_id();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT d.* FROM application_document_dispatches d JOIN applications a ON a.id=d.application_id WHERE d.id=? AND a.user_id=?');$s->execute([$id,$uid]);$r=$s->fetch();if(!$r)throw new RuntimeException('Copie introuvable.');$file=APP_ROOT.'/storage/document-dispatches/'.basename($r['snapshot_filename']);if(!is_file($file)||!hash_equals($r['snapshot_sha256'],hash_file('sha256',$file)))throw new RuntimeException('Copie absente ou altérée.');$name=preg_replace('/[^a-zA-Z0-9_.-]/','_',(string)$r['snapshot_original_name']);header('Content-Type: '.$r['snapshot_mime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.$name.'"');header('Cache-Control: private, no-store');header('Content-Length: '.filesize($file));readfile($file);
}catch(Throwable $e){http_response_code(404);header('Content-Type: text/plain; charset=utf-8');echo $e->getMessage();}
